import { readFileSync } from 'node:fs';

// Generated by sync:concept-repair after source validation. The site does not
// import the content package across its boundary or bundle public JSON.
const manifest = JSON.parse(readFileSync(new URL('../../.generated/concept-repair.json', import.meta.url), 'utf8'));
export const { cases, checks, connections, originPoints, historyLinks } = manifest;
export const isReviewPreview = () => manifest.enabled === true;
const reviewPath = '/review/concept-repair/';
export const modelPath = (id) => `${reviewPath}${id}.3dss.json`;
export const viewerPath = (id, title) => `/app/viewer?${new URLSearchParams({ model: modelPath(id), from: 'review', return: reviewPath, title, noads: '1' })}`;
